  "dispatch_typed": {
    title: "The table declares one handler shape, and every entry is held to it",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: true,
    improves: "dispatch_untyped",
    misuseOf: null,
    python: "from collections.abc import Callable\nfrom dataclasses import dataclass\nfrom typing import Literal\n\ntype Status = Literal[\"draft\", \"sent\", \"paid\"]\n\n\n@dataclass(frozen=True)\nclass Invoice:\n    number: str\n    status: Status\n\n\ndef send(invoice: Invoice) -> Invoice:\n    return Invoice(invoice.number, \"sent\")\n\n\ndef record_payment(invoice: Invoice) -> Invoice:\n    return Invoice(invoice.number, \"paid\")\n\n\ndef keep(invoice: Invoice) -> Invoice:\n    return invoice\n\n\nHANDLERS: dict[Status, Callable[[Invoice], Invoice]] = {\n    \"draft\": send,\n    \"sent\": record_payment,\n    \"paid\": keep,\n}\n\n\ndef advance(invoice: Invoice) -> Invoice:\n    return HANDLERS[invoice.status](invoice)\n\n\nassert advance(Invoice(\"INV-7\", \"draft\")).status == \"sent\"\nassert advance(Invoice(\"INV-7\", \"paid\")).status == \"paid\"\n",
    typescript: "type Status = \"draft\" | \"sent\" | \"paid\";\n\ntype Invoice = { readonly number: string; readonly status: Status };\n\nfunction send(invoice: Invoice): Invoice {\n  return { number: invoice.number, status: \"sent\" };\n}\n\nfunction recordPayment(invoice: Invoice): Invoice {\n  return { number: invoice.number, status: \"paid\" };\n}\n\nfunction keep(invoice: Invoice): Invoice {\n  return invoice;\n}\n\nconst handlers: Record<Status, (invoice: Invoice) => Invoice> = {\n  draft: send,\n  sent: recordPayment,\n  paid: keep,\n};\n\nexport function advance(invoice: Invoice): Invoice {\n  return handlers[invoice.status](invoice);\n}\n",
  },
