  "email_parse": {
    title: "An EmailAddress records that parse_email accepted it",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: "email_checked",
    misuseOf: null,
    python: "from typing import NewType\n\nEmailAddress = NewType(\"EmailAddress\", str)\n\n\ndef parse_email(raw: str) -> EmailAddress | None:\n    candidate = raw.strip()\n    local, sep, domain = candidate.partition(\"@\")\n    if not sep or not local or \"@\" in domain or \".\" not in domain:\n        return None\n    return EmailAddress(candidate)\n\n\ndef send_receipt(to: EmailAddress) -> str:\n    return f\"receipt sent to {to}\"\n\n\ndef checkout(raw_form_field: str) -> str:\n    email = parse_email(raw_form_field)\n    if email is None:\n        return \"ask the user again\"\n    return send_receipt(email)\n",
    typescript: "declare const emailBrand: unique symbol;\ntype EmailAddress = string & { readonly [emailBrand]: true };\n\nfunction parseEmail(raw: string): EmailAddress | null {\n  const candidate = raw.trim();\n  const at = candidate.indexOf(\"@\");\n  const local = candidate.slice(0, at < 0 ? 0 : at);\n  const domain = candidate.slice(at + 1);\n  if (at < 0 || !local || domain.includes(\"@\") || !domain.includes(\".\")) {\n    return null;\n  }\n  return candidate as EmailAddress;\n}\n\nfunction sendReceipt(to: EmailAddress): string {\n  return `receipt sent to ${to}`;\n}\n\nexport function checkout(rawFormField: string): string {\n  const email = parseEmail(rawFormField);\n  if (email === null) {\n    return \"ask the user again\";\n  }\n  return sendReceipt(email);\n}\n",
  },
