    python: "import json\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass User:\n    name: str\n    age: int\n\n\ndef parse_user(body: str) -> User:\n    data = json.loads(body)\n    match data:\n        case {\"name\": str(name), \"age\": int(age)}:\n            return User(name, age)\n        case _:\n            raise ValueError(f\"not a user: {body}\")\n\n\ndef greeting(user: User) -> str:\n    return f\"hello {user.name}\"\n\n\ndef can_vote(user: User) -> bool:\n    return user.age >= 18\n\n\ndef summary(body: str) -> str:\n    user = parse_user(body)\n    return f\"{greeting(user)}, can vote: {can_vote(user)}\"\n\n\nassert summary('{\"name\": \"Ada\", \"age\": 36}') == \"hello Ada, can vote: True\"\n",
    typescript: "type User = { readonly name: string; readonly age: number };\n\nfunction parseUser(body: string): User {\n  const data: unknown = JSON.parse(body);\n  if (\n    typeof data !== \"object\" ||\n    data === null ||\n    !(\"name\" in data) ||\n    !(\"age\" in data) ||\n    typeof data.name !== \"string\" ||\n    typeof data.age !== \"number\"\n  ) {\n    throw new Error(`not a user: ${body}`);\n  }\n  return { name: data.name, age: data.age };\n}\n\nfunction greeting(user: User): string {\n  return `hello ${user.name}`;\n}\n\nfunction canVote(user: User): boolean {\n  return user.age >= 18;\n}\n\nexport function summary(body: string): string {\n  const user = parseUser(body);\n  return `${greeting(user)}, can vote: ${canVote(user)}`;\n}\n",
