  "higher_order": {
    title: "After retry, fetch keeps its full signature",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: "retry_any",
    misuseOf: null,
    python: "from collections.abc import Callable\n\n\ndef retry[**P, R](times: int, operation: Callable[P, R]) -> Callable[P, R]:\n    def attempt(*args: P.args, **kwargs: P.kwargs) -> R:\n        failures = 0\n        while True:\n            try:\n                return operation(*args, **kwargs)\n            except ConnectionError:\n                failures += 1\n                if failures >= times:\n                    raise\n    return attempt\n\n\ndef fetch(url: str, timeout: int) -> str:\n    return f\"GET {url} within {timeout}s\"\n\n\npatient_fetch = retry(3, fetch)\nresult: str = patient_fetch(\"https://example.test\", 10)\n",
    typescript: "class ConnectionLost extends Error {}\n\nfunction retry<A extends unknown[], R>(\n  times: number,\n  operation: (...args: A) => R,\n): (...args: A) => R {\n  return (...args: A): R => {\n    let failures = 0;\n    for (;;) {\n      try {\n        return operation(...args);\n      } catch (error) {\n        if (!(error instanceof ConnectionLost)) throw error;\n        failures += 1;\n        if (failures >= times) throw error;\n      }\n    }\n  };\n}\n\nfunction fetch(url: string, timeout: number): string {\n  return `GET ${url} within ${timeout}s`;\n}\n\nconst patientFetch = retry(3, fetch);\nexport const result: string = patientFetch(\"https://example.test\", 10);\n",
  },
