  "json_blob": {
    title: "Json travels through every signature, and every use needs a cast",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: null,
    misuseOf: null,
    python: "from typing import cast\n\ntype Json = None | bool | int | float | str | list[\"Json\"] | dict[str, \"Json\"]\n\n\ndef line_total(line: Json) -> Json:\n    fields = cast(dict[str, Json], line)\n    return cast(int, fields[\"pence\"]) * cast(int, fields[\"quantity\"])\n\n\ndef invoice_total(lines: Json) -> Json:\n    rows = cast(list[Json], lines)\n    return sum(cast(int, line_total(row)) for row in rows)\n\n\ndef is_large(lines: Json) -> bool:\n    return cast(int, invoice_total(lines)) > 1000\n",
    typescript: "type Json = null | boolean | number | string | Json[] | { [key: string]: Json };\n\nexport function lineTotal(line: Json): Json {\n  const fields = line as { [key: string]: Json };\n  return (fields.pence as number) * (fields.quantity as number);\n}\n\nexport function invoiceTotal(lines: Json): Json {\n  return (lines as Json[]).reduce((sum: number, row) => sum + (lineTotal(row) as number), 0);\n}\n\nexport function isLarge(lines: Json): boolean {\n  return (invoiceTotal(lines) as number) > 1000;\n}\n",
  },
