    python: "from dataclasses import dataclass\nfrom typing import NewType\n\nPence = NewType(\"Pence\", int)\n\n\n@dataclass(frozen=True)\nclass Line:\n    item: str\n    pence: Pence\n    quantity: int\n\n\ndef parse_line(raw: object) -> Line:\n    match raw:\n        case {\"item\": str(item), \"pence\": int(pence), \"quantity\": int(quantity)}:\n            return Line(item, Pence(pence), quantity)\n        case _:\n            raise ValueError(f\"not a line: {raw!r}\")\n\n\ndef line_total(line: Line) -> Pence:\n    return Pence(line.pence * line.quantity)\n\n\ndef invoice_total(lines: list[Line]) -> Pence:\n    return Pence(sum(line_total(line) for line in lines))\n\n\ndef is_large(lines: list[Line]) -> bool:\n    return invoice_total(lines) > 1000\n\n\nbasket = [parse_line({\"item\": \"saddle\", \"pence\": 155, \"quantity\": 4})]\nassert invoice_total(basket) == 620\nassert is_large(basket) is False\n",
    typescript: "declare const penceBrand: unique symbol;\ntype Pence = number & { readonly [penceBrand]: true };\n\ntype Line = { readonly item: string; readonly pence: Pence; readonly quantity: number };\n\nfunction parseLine(raw: unknown): Line {\n  if (\n    typeof raw !== \"object\" ||\n    raw === null ||\n    !(\"item\" in raw) ||\n    !(\"pence\" in raw) ||\n    !(\"quantity\" in raw) ||\n    typeof raw.item !== \"string\" ||\n    typeof raw.pence !== \"number\" ||\n    typeof raw.quantity !== \"number\"\n  ) {\n    throw new Error(\"not a line\");\n  }\n  return { item: raw.item, pence: raw.pence as Pence, quantity: raw.quantity };\n}\n\nfunction lineTotal(line: Line): Pence {\n  return (line.pence * line.quantity) as Pence;\n}\n\nexport function invoiceTotal(lines: readonly Line[]): Pence {\n  return lines.reduce((sum, line) => sum + lineTotal(line), 0) as Pence;\n}\n\nexport function isLarge(lines: readonly Line[]): boolean {\n  return invoiceTotal(lines) > 1000;\n}\n\nexport const basket = [parseLine({ item: \"saddle\", pence: 155, quantity: 4 })];\n",
