  "result_chain": {
    title: "quote returns Ok with a price, or Err with the reason",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: true,
    improves: "nullable_chain",
    misuseOf: null,
    python: "from collections.abc import Callable\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass Ok[T]:\n    value: T\n\n\n@dataclass(frozen=True)\nclass Err:\n    reason: str\n\n\ntype Result[T] = Ok[T] | Err\n\n\ndef and_then[T, U](result: Result[T], step: Callable[[T], Result[U]]) -> Result[U]:\n    match result:\n        case Ok(value):\n            return step(value)\n        case Err():\n            return result\n\n\ndef parse_quantity(text: str) -> Result[int]:\n    return Ok(int(text)) if text.isdigit() else Err(f\"not a number: {text!r}\")\n\n\ndef check_stock(quantity: int) -> Result[int]:\n    return Ok(quantity) if quantity <= 10 else Err(\"only 10 in stock\")\n\n\ndef price(quantity: int) -> Result[int]:\n    return Ok(quantity * 250)\n\n\ndef quote(text: str) -> Result[int]:\n    return and_then(and_then(parse_quantity(text), check_stock), price)\n\n\nassert quote(\"3\") == Ok(750)\nassert quote(\"99\") == Err(\"only 10 in stock\")\nassert quote(\"many\") == Err(\"not a number: 'many'\")\n",
    typescript: "type Ok<T> = { readonly kind: \"ok\"; readonly value: T };\ntype Err = { readonly kind: \"err\"; readonly reason: string };\ntype Result<T> = Ok<T> | Err;\n\nfunction ok<T>(value: T): Result<T> {\n  return { kind: \"ok\", value };\n}\n\nfunction err(reason: string): Result<never> {\n  return { kind: \"err\", reason };\n}\n\nfunction andThen<T, U>(result: Result<T>, step: (value: T) => Result<U>): Result<U> {\n  return result.kind === \"ok\" ? step(result.value) : result;\n}\n\nfunction parseQuantity(text: string): Result<number> {\n  return /^\\d+$/.test(text) ? ok(Number(text)) : err(`not a number: ${text}`);\n}\n\nfunction checkStock(quantity: number): Result<number> {\n  return quantity <= 10 ? ok(quantity) : err(\"only 10 in stock\");\n}\n\nfunction price(quantity: number): Result<number> {\n  return ok(quantity * 250);\n}\n\nexport function quote(text: string): Result<number> {\n  return andThen(andThen(parseQuantity(text), checkStock), price);\n}\n",
  },
