  "the_program_fixed": {
    title: "The bill of materials and the invoice, with the types doing the work",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: true,
    improves: null,
    misuseOf: null,
    python: "from dataclasses import dataclass\nfrom enum import StrEnum\nfrom typing import Literal, NewType\n\nPence = NewType(\"Pence\", int)\nRate = NewType(\"Rate\", float)\nCustomerId = NewType(\"CustomerId\", str)\nProductId = NewType(\"ProductId\", str)\ntype Status = Literal[\"draft\", \"sent\", \"paid\"]\n\n\nclass Unit(StrEnum):\n    EACH = \"each\"\n    METERS = \"meters\"\n    KILOGRAMS = \"kilograms\"\n\n\n@dataclass(frozen=True)\nclass BomLine:\n    part_no: str\n    description: str\n    qty: int\n    unit: Unit\n    cost: Pence\n\n\ndef invoice_line(description: str, price: Pence, quantity: int, taxed: bool) -> str:\n    note = \" +tax\" if taxed else \"\"\n    return f\"{description} x{quantity} at {price}d{note}\"\n\n\ndef invoice_total(prices: list[Pence]) -> Pence:\n    return Pence(sum(prices))\n\n\ndef apply_discount(total: Pence, rate: Rate) -> Pence:\n    return Pence(round(total * (1 - rate)))\n\n\ndef advance(status: Status) -> Status:\n    match status:\n        case \"draft\":\n            return \"sent\"\n        case \"sent\":\n            return \"paid\"\n        case \"paid\":\n            return \"paid\"\n\n\ndef bill(customer: CustomerId, product: ProductId) -> str:\n    return f\"invoice {customer} for one {product}\"\n\n\ndef parse_bom_line(row: str) -> BomLine | None:\n    match row.split(\",\"):\n        case [part_no, description, qty_text, unit_text, cost_text]:\n            if not qty_text.isdigit() or not cost_text.isdigit():\n                return None\n            try:\n                unit = Unit(unit_text)\n            except ValueError:\n                return None\n            return BomLine(part_no, description, int(qty_text), unit, Pence(int(cost_text)))\n        case _:\n            return None\n\n\nassert advance(\"draft\") == \"sent\"\nassert invoice_total([Pence(24), Pence(24), Pence(24)]) == 72\nassert apply_discount(Pence(1250), Rate(0.1)) == 1125\nassert parse_bom_line(\"F-101,down tube,1,meters,155\") == BomLine(\n    \"F-101\", \"down tube\", 1, Unit.METERS, Pence(155)\n)\nassert parse_bom_line(\"F-101,down tube,one,meters,155\") is None\n",
    typescript: "declare const penceBrand: unique symbol;\ndeclare const rateBrand: unique symbol;\ndeclare const customerBrand: unique symbol;\ndeclare const productBrand: unique symbol;\n\ntype Pence = number & { readonly [penceBrand]: true };\ntype Rate = number & { readonly [rateBrand]: true };\ntype CustomerId = string & { readonly [customerBrand]: true };\ntype ProductId = string & { readonly [productBrand]: true };\ntype Status = \"draft\" | \"sent\" | \"paid\";\ntype Unit = \"each\" | \"meters\" | \"kilograms\";\n\ntype BomLine = {\n  readonly partNo: string;\n  readonly description: string;\n  readonly qty: number;\n  readonly unit: Unit;\n  readonly cost: Pence;\n};\n\nfunction pence(n: number): Pence {\n  return n as Pence;\n}\n\nexport function invoiceLine(description: string, price: Pence, quantity: number, taxed: boolean): string {\n  const note = taxed ? \" +tax\" : \"\";\n  return `${description} x${quantity} at ${price}d${note}`;\n}\n\nexport function invoiceTotal(prices: readonly Pence[]): Pence {\n  return pence(prices.reduce((sum, price) => sum + price, 0));\n}\n\nfunction rate(n: number): Rate {\n  return n as Rate;\n}\n\nexport function applyDiscount(total: Pence, discount: Rate): Pence {\n  return pence(Math.round(total * (1 - discount)));\n}\n\nexport const discounted = applyDiscount(pence(1250), rate(0.1));\n\nexport function advance(status: Status): Status {\n  switch (status) {\n    case \"draft\":\n      return \"sent\";\n    case \"sent\":\n      return \"paid\";\n    case \"paid\":\n      return \"paid\";\n  }\n}\n\nexport function bill(customer: CustomerId, product: ProductId): string {\n  return `invoice ${customer} for one ${product}`;\n}\n\nfunction isUnit(value: string): value is Unit {\n  return value === \"each\" || value === \"meters\" || value === \"kilograms\";\n}\n\nfunction isRow(fields: string[]): fields is [string, string, string, string, string] {\n  return fields.length === 5;\n}\n\nexport function parseBomLine(row: string): BomLine | null {\n  const fields = row.split(\",\");\n  if (!isRow(fields)) return null;\n  const [partNo, description, qtyText, unitText, costText] = fields;\n  if (!/^\\d+$/.test(qtyText) || !/^\\d+$/.test(costText) || !isUnit(unitText)) return null;\n  return { partNo, description, qty: Number(qtyText), unit: unitText, cost: pence(Number(costText)) };\n}\n",
  },
