    python: "--- a/example.py\n+++ b/example.py\n@@ -1,18 +1,43 @@\n-def find_user_id(login: str) -> str | None:\n-    return \"u7\" if login == \"ada\" else None\n+from collections.abc import Callable\n+from dataclasses import dataclass\n \n \n-def find_cart(user_id: str) -> list[str] | None:\n-    return [\"book\"] if user_id == \"u7\" else None\n+@dataclass(frozen=True)\n+class Ok[T]:\n+    value: T\n \n \n-def first_item(login: str) -> str | None:\n-    user_id = find_user_id(login)\n-    if user_id is None:\n-        return None\n-    cart = find_cart(user_id)\n-    if cart is None:\n-        return None\n-    if not cart:\n-        return None\n-    return cart[0]\n+@dataclass(frozen=True)\n+class Err:\n+    reason: str\n+\n+\n+type Result[T] = Ok[T] | Err\n+\n+\n+def and_then[T, U](result: Result[T], step: Callable[[T], Result[U]]) -> Result[U]:\n+    match result:\n+        case Ok(value):\n+            return step(value)\n+        case Err():\n+            return result\n+\n+\n+def find_user_id(login: str) -> Result[str]:\n+    return Ok(\"u7\") if login == \"ada\" else Err(f\"no user for login {login!r}\")\n+\n+\n+def find_cart(user_id: str) -> Result[list[str]]:\n+    return Ok([\"book\"]) if user_id == \"u7\" else Err(f\"no cart for {user_id}\")\n+\n+\n+def head(items: list[str]) -> Result[str]:\n+    return Ok(items[0]) if items else Err(\"the cart is empty\")\n+\n+\n+def first_item(login: str) -> Result[str]:\n+    return and_then(and_then(find_user_id(login), find_cart), head)\n+\n+\n+assert first_item(\"ada\") == Ok(\"book\")\n+assert first_item(\"bob\") == Err(\"no user for login 'bob'\")\n",
    typescript: "--- a/example.ts\n+++ b/example.ts\n@@ -1,19 +1,32 @@\n-function findUserId(login: string): string | null {\n-  return login === \"ada\" ? \"u7\" : null;\n+type Ok<T> = { readonly kind: \"ok\"; readonly value: T };\n+type Err = { readonly kind: \"err\"; readonly reason: string };\n+type Result<T> = Ok<T> | Err;\n+\n+function ok<T>(value: T): Result<T> {\n+  return { kind: \"ok\", value };\n }\n \n-function findCart(userId: string): string[] | null {\n-  return userId === \"u7\" ? [\"book\"] : null;\n+function err(reason: string): Result<never> {\n+  return { kind: \"err\", reason };\n }\n \n-export function firstItem(login: string): string | null {\n-  const userId = findUserId(login);\n-  if (userId === null) {\n-    return null;\n-  }\n-  const cart = findCart(userId);\n-  if (cart === null) {\n-    return null;\n-  }\n-  return cart[0] ?? null;\n+function andThen<T, U>(result: Result<T>, step: (value: T) => Result<U>): Result<U> {\n+  return result.kind === \"ok\" ? step(result.value) : result;\n+}\n+\n+function findUserId(login: string): Result<string> {\n+  return login === \"ada\" ? ok(\"u7\") : err(`no user for login ${login}`);\n+}\n+\n+function findCart(userId: string): Result<string[]> {\n+  return userId === \"u7\" ? ok([\"book\"]) : err(`no cart for ${userId}`);\n+}\n+\n+function head(items: string[]): Result<string> {\n+  const first = items[0];\n+  return first === undefined ? err(\"the cart is empty\") : ok(first);\n+}\n+\n+export function firstItem(login: string): Result<string> {\n+  return andThen(andThen(findUserId(login), findCart), head);\n }\n",
